import json,numpy as np
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib import font_manager
from mtr_project.paths import ROOT,write_json
font_manager.fontManager.addfont('/mnt/c/Windows/Fonts/msyh.ttc');plt.rcParams['font.family']=font_manager.FontProperties(fname='/mnt/c/Windows/Fonts/msyh.ttc').get_name();plt.rcParams['axes.unicode_minus']=False
base=ROOT/'runs/project-v3/language-choice-v1';a=json.loads((base/'report/evaluation.json').read_text());out=base/'report-reviewed';out.mkdir(exist_ok=True)
matched=0;baseline_matched=0;branch_cases=[]
for r in a['windows']:
 s=json.loads((ROOT/'runs'/r['source_window']['run']/'ambiguity_aware_feasibility.json').read_text());by_id={p['candidate']:p for p in s['candidates']}
 expected='turn_'+r['source_window']['action'];choice=next(c for c in r['choices'] if c['action']==expected)
 matched+=choice['choice']['candidate'] is not None
 baseline_matched+=choice['choice']['candidate'] is not None and choice['choice']['candidate']==r['checked_baseline_candidate']
 selected=[by_id[c['choice']['candidate']]['route']['route'] for c in r['choices'] if c['choice']['candidate'] is not None]
 different=any(x!=y and x[:len(y)]!=y and y[:len(x)]!=x for x in selected for y in selected)
 if different:branch_cases.append(r['number'])
summary={'turn_coverage':{'numerator':matched,'denominator':7},'left':{'numerator':2,'denominator':5},'right':{'numerator':1,'denominator':2},'lane_change_any':{'numerator':0,'denominator':7},'distinct_road_branch_choice':{'numerator':len(branch_cases),'denominator':7},'selected_expected_turn_equals_checked_baseline':baseline_matched,'interpretation':'Same route with different 6s angle is not a branch change. Retrospective small sample frequencies only.'}
assert matched==3 and not branch_cases
write_json(out/'reviewed-summary.json',summary)
labels=['\u5bf9\u5e94\u65b9\u5411\u8f6c\u5f2f\n（\u5168\u90e87\u573a\u666f）','\u5de6\u8f6c\n（5\u4e2a\u5de6\u8f6c\u573a\u666f）','\u53f3\u8f6c\n（2\u4e2a\u53f3\u8f6c\u573a\u666f）','\u6362\u9053\n（7\u573a\u666f，\u975e\u4e13\u95e8\u6362\u9053\u96c6）','\u8bed\u8a00\u5207\u6362\u9053\u8def\u5206\u652f\n（\u540c\u4e00\u573a\u666f\u591a\u79cd\u6307\u4ee4）'];nums=[3,2,1,0,0];dens=[7,5,2,7,7]
fig,ax=plt.subplots(figsize=(12,5.8));x=np.arange(5);ax.bar(x,np.array(nums)/dens*100,color=['#247e91','#9052b0','#158b75','#8897aa','#cf5260'],width=.6);ax.set_ylim(0,110);ax.set_ylabel('\u672c\u6b21\u6837\u672c\u6bd4\u4f8b（%）');ax.set_xticks(x,labels,fontsize=10);ax.set_title('\u5f53\u524d\u80fd\u529b：\u80fd\u9009\u5230\u90e8\u5206\u8f6c\u5f2f，\u4f46\u5c1a\u672a\u8bc1\u660e\u8bed\u8a00\u80fd\u5207\u6362\u9053\u8def\u65b9\u5411',fontsize=15,pad=20);ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.15);ax.set_axisbelow(True)
for i,(n,d) in enumerate(zip(nums,dens)):ax.text(i,n/d*100+4,f'{n}/{d} = {n/d:.0%}',ha='center',fontsize=14,fontweight='bold')
fig.text(.03,.015,'\u901a\u8fc7\u7684\u662f\u79bb\u7ebf\u6709\u9650\u68c0\u67e5，\u4e0d\u662f\u5b9e\u9645\u9a7e\u9a76\u6210\u529f\u7387；7\u4e2a\u7cbe\u9009\u7a97\u53e3、448\u6761\u5019\u9009。\u6362\u9053\u4e0e\u5206\u652f\u9009\u62e9\u5c1a\u7f3a\u4e13\u95e8\u6837\u672c。',fontsize=10);fig.tight_layout(rect=[0,.06,1,1]);fig.savefig(out/'main-findings.png',dpi=160);plt.close(fig)
text=['\u8bed\u8a00\u8def\u7ebf\u9009\u62e9\u5b9e\u9a8c（2026-10-19）','','\u4e3b\u7ed3\u8bba：\u5bf9\u5e94\u5b9e\u9645\u8f6c\u5f2f\u65b9\u5411\u53ef\u90093/7（43%）；\u5de6\u8f6c2/5，\u53f3\u8f6c1/2。\u6362\u90530/7。\u540c\u4e00\u573a\u666f\u901a\u8fc7\u4e0d\u540c\u6307\u4ee4\u9009\u5230\u4e0d\u540c\u9053\u8def\u5206\u652f0/7。\u4ee5\u4e0a\u662f\u5c0f\u6837\u672c\u79bb\u7ebf\u8986\u76d6\u7387，\u4e0d\u662f\u90e8\u7f72\u6210\u529f\u6982\u7387。','','35\u6b21\u6307\u4ee4\u4e2d8\u6b21\u88ab\u539f\u89c4\u5219\u9009\u62e9，\u4f46\u4e0d\u80fd\u4f5c\u4e3a\u603b\u6210\u529f\u7387：\u4e0d\u540c\u573a\u666f\u5e76\u4e0d\u652f\u6301\u6240\u67095\u79cd\u52a8\u4f5c，\u800c\u4e14\u539f\u76f4\u884c\u6807\u7b7e\u5b58\u5728\u8bed\u4e49\u95ee\u9898。','04\u573a\u666f\u7684\u76f4\u884c\u5019\u900914\u4e0e\u53f3\u8f6c\u5019\u900951\u5747\u6cbf L68542 -> C68708。\u533a\u522b\u53ea\u662f6\u79d2\u8f6c\u89d2\u6709\u6ca1\u6709\u8fbe\u523030\u5ea6，\u4e0d\u80fd\u7b97\u8bed\u8a00\u6210\u529f\u5207\u6362\u9053\u8def\u5206\u652f。','\u5bf9\u5e94\u8f6c\u5f2f\u9009\u62e9\u4e0e\u4e0d\u52a0\u8bed\u8a00\u7684\u6700\u9ad8\u5206\u901a\u8fc7\u68c0\u67e5\u5019\u9009\u4e00\u81f4\u7684\u6b21\u6570：'+str(baseline_matched)+'/3。\u56e0\u6b64\u4e0d\u80fd\u628a\u5168\u90e83\u4e2a\u8f6c\u5f2f\u6210\u529f\u5f52\u56e0\u4e8e\u8bed\u8a00。','','\u5931\u8d25\u4f4d\u7f6e：','01：\u5b58\u5728\u5de6\u8f6c\u5019\u900931，\u4f46\u88ab\u6052\u901f\u969c\u788d\u7269\u5916\u63a8\u7684\u78b0\u649e\u68c0\u67e5\u62d2\u7edd。\u8be5\u68c0\u67e5\u662f\u7b80\u5316\u5047\u8bbe，\u4e0d\u7b49\u4e8e\u771f\u5b9e\u5fc5\u649e。','02：\u5b58\u5728\u5de6\u8f6c\u5019\u900940，\u4f46\u88ab\u8f66\u8eab\u8fb9\u754c\u548c\u6052\u901f\u78b0\u649e\u68c0\u67e5\u62d2\u7edd。','03：\u6ca1\u6709\u88ab\u73b0\u6709\u9053\u8def\u5339\u914d\u4e0e\u52a8\u4f5c\u89c4\u5219\u8ba4\u4f5c\u5de6\u8f6c\u7684\u5019\u9009；\u4e0d\u8868\u793a64\u6761\u91cc\u5b8c\u5168\u6ca1\u6709\u5f2f\u7ebf。','07：4\u6761\u9053\u8def\u5339\u914d\u7684\u53f3\u8f6c\u5019\u9009\u5747\u88ab\u8f66\u8eab\u8fb9\u754c\u68c0\u67e5\u62d2\u7edd。','05、06：\u5404\u80fd\u9009\u4e2d\u4e00\u6761\u5de6\u8f6c；04：\u80fd\u9009\u4e2d\u53f3\u8f6c。','','\u5b9e\u9a8c\u65b9\u6cd5：','\u9884\u8bad\u7ec3MTR\u5bf97\u4e2a\u56fa\u5b9a\u7a97\u53e3\u5404\u751f\u621064\u6761\u5019\u9009，\u5171448\u6761；\u73b0\u6709\u6709\u9650\u5e73\u6ed1\u5904\u7406\u540e\u505a\u9053\u8def、\u8fd0\u52a8\u548c\u7b80\u5316\u78b0\u649e\u68c0\u67e5，\u518d\u7531\u82f1\u6587\u89c4\u5219\u89e3\u6790\u5668\u9009\u62e9\u7b26\u5408\u6307\u4ee4\u4e14\u5206\u6570\u6700\u9ad8\u7684\u5019\u9009。\u6ca1\u6709\u63a5\u5165\u8bed\u8a00\u5927\u6a21\u578b，\u6ca1\u6709\u6267\u884c\u8f66\u8f86\u63a7\u5236。\u8f93\u5165\u7a97\u53e3\u5728\u672c\u8f6eMTR\u63a8\u7406\u524d\u5df2\u56fa\u5b9a。','\u4f7f\u7528\u4fee\u590d\u540e\u7684\u5386\u53f2\u5165\u53e3\u96c6\u5408，\u907f\u514d\u8fc7\u65e9\u56fa\u5b9a\u5230\u4e00\u6761\u91cd\u53e0\u5165\u53e3。\u4fdd\u7559\u539f\u6a21\u578b\u6700\u7ec85\u6761\u4f5c\u5bf9\u7167：\u5de6\u8f6c\u8986\u76d6\u7531\u6700\u7ec85\u6761\u76840/5\u63d0\u5347\u5230\u5168\u90e864\u6761\u76842/5；\u53f3\u8f6c\u4e24\u8005\u57471/2。','\u4e3b\u7edf\u8ba1\u56fe：main-findings.png；\u9009\u62e9\u77e9\u9635：choice-matrix.png；\u9010\u573a\u666f\u4e94\u6307\u4ee4\u8def\u7ebf\u56fe：scene-01.png\u81f3scene-07.png。\u56fe\u4e2d\u865a\u7ebf\u4e3a\u771f\u5b9e\u672a\u6765，\u53ea\u7528\u4e8e\u5bf9\u7167。','','\u4e0b\u4e00\u6b65：','1. \u4fee\u6b63\u76f4\u884c\u4e0e\u5f2f\u9053\u7684\u8bed\u4e49\u5b9a\u4e49：\u660e\u786e\u9053\u8def\u5206\u652f\u610f\u56fe\u548c6\u79d2\u8fd0\u52a8\u8f6c\u89d2\u662f\u4e24\u4ef6\u4e8b。','2. \u4e13\u95e8\u5bfb\u627e\u540c\u4e00\u5165\u53e3\u786e\u6709\u591a\u4e2a\u65b9\u5411\u7684\u7a97\u53e3，\u5e76\u5355\u72ec\u5efa\u7acb\u6362\u9053\u6837\u672c\u96c6；7\u4e2a\u8f6c\u5f2f\u6837\u4f8b\u4e0d\u80fd\u4ee3\u8868\u6362\u9053\u603b\u4f53\u80fd\u529b。','3. \u9488\u5bf907\u7684\u53f3\u8f6c\u8f66\u8eab\u8fb9\u754c、01/02\u7684\u6052\u901f\u78b0\u649e\u62d2\u7edd\u9010\u4e00\u8bca\u65ad，\u4e0d\u80fd\u76f4\u63a5\u653e\u5bbd\u9608\u503c\u8ba9\u5019\u9009\u901a\u8fc7。']
(out/'READ_ME_ZH.txt').write_text('\n'.join(text),encoding='utf-8');print(json.dumps(summary))
